/// <summary>
/// Data provider for the Demo print format report.
/// Extends <c>SrsReportDataProviderBase</c> and populates the <c>ConDemoPrintFmtTmp</c> temporary table.
/// </summary>
[
    SRSReportParameterAttribute(classStr(ConDemoPrintFmtContract))
]
public class ConDemoPrintFmtDP extends SrsReportDataProviderBase
{
    ConDemoPrintFmtTmp conDemoPrintFmtTmp;

}

