/// <summary>
/// Returns the temporary table buffer used by the report dataset.
/// </summary>
/// <returns>The <c>ConDemoPrintFmtTmp</c> table buffer.</returns>
[SRSReportDataSetAttribute(tableStr(ConDemoPrintFmtTmp))]
public ConDemoPrintFmtTmp getConDemoPrintFmtTmp()
{
    select conDemoPrintFmtTmp;
    return conDemoPrintFmtTmp;
}

